draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50, H/2 + 20);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // dog ear
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 40);
  ctx.lineTo(W/2 - 25, H/2 - 60);
  ctx.stroke();

  // dog front leg
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 10);
  ctx.lineTo(W/2 + 40, H/2 + 30);
  ctx.stroke();

  // dog back leg
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 + 30);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();

  // bow
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 + 20);
  ctx.lineTo(W/2 + 90, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2 + 20, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // inviting to play
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 70, H/2 + 70);
  ctx.stroke();

  // head movement
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 10, H/2 - 30 + Math.cos(t) * 10, 20, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
